template <typename T>
__aicore__ inline void AddImpl(__ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, const int32_t& calCount)
{
    static_assert(
        (SupportType<
            T, uint8_t, int8_t, half, uint16_t, int16_t, bfloat16_t, uint32_t, int32_t, float, int64_t, uint64_t,
            complex32, complex64>()),
        "current data type is not supported on current device!");
    if constexpr (SupportBytes<T, 8>() || SupportType<T, complex32>()) {
        BinaryContinuousImplTemplate<
            T, Reg::RegTensor<T, Reg::RegTraitNumTwo>,
            Reg::Add<T, Reg::MaskMergeMode::ZEROING, Reg::RegTensor<T, Reg::RegTraitNumTwo>>>(
            dst, src0, src1, calCount);
    } else {
        BinaryContinuousImplTemplate<T, Reg::RegTensor<T>, Reg::Add<T, Reg::MaskMergeMode::ZEROING, Reg::RegTensor<T>>>(
            dst, src0, src1, calCount);
    }
}

template <typename T, typename RegT, typename RegU>
__aicore__ inline void AddDeqRelu(RegU& dstReg, RegT& srcReg0, RegT& srcReg1, Reg::MaskReg& mask)
{
    // max(float(srcReg0 + srcReg1) * (1/131072) * g_deqValue * 131072, 0)
    Reg::RegTensor<float> tmpReg;
    Reg::Add(srcReg0, srcReg0, srcReg1, mask);
    Reg::Cast<float, int32_t, CastParam::s322floatCastTrait>(tmpReg, srcReg0, mask);
    Reg::Muls(tmpReg, tmpReg, static_cast<float>(DEQ_SHIFT_RIGHT_17_BIT), mask);
    Reg::Muls(tmpReg, tmpReg, static_cast<float>(Internal::g_deqValue), mask);
    Reg::Muls(tmpReg, tmpReg, static_cast<float>(DEQ_SHIFT_LEFT_17_BIT), mask);
    Reg::Maxs(tmpReg, tmpReg, (T)0, mask);
    Reg::Cast<half, float, CastParam::float2halfCastTrait>(dstReg, tmpReg, mask);
    Reg::Pack<uint16_t, uint32_t, Reg::HighLowPart::LOWEST>(
        (Reg::RegTensor<uint16_t>&)dstReg, (Reg::RegTensor<uint32_t>&)dstReg);
}

template <typename T, typename RegT>
__aicore__ inline void AddRelu(RegT& dstReg, RegT& srcReg0, RegT& srcReg1, Reg::MaskReg& mask)
{
    Reg::Add(dstReg, srcReg0, srcReg1, mask);
    Reg::Maxs(dstReg, dstReg, (T)0, mask);
}

template <typename T1, typename T2, typename RegT, typename RegU>
__simd_callee__ inline void AddReluCast(RegT& dstReg, RegU& src0Reg, RegU& src1Reg, Reg::MaskReg& mask)
{
    Reg::Add(src0Reg, src0Reg, src1Reg, mask);
    Reg::Maxs(src0Reg, src0Reg, static_cast<T2>(0), mask);
    if constexpr (IsSameType<T2, float>::value) {
        Reg::Cast<T1, T2, CastParam::AddReluCastTrait>(dstReg, src0Reg, mask);
        Reg::Pack<uint16_t, uint32_t, Reg::HighLowPart::LOWEST>(
            (Reg::RegTensor<uint16_t>&)dstReg, (Reg::RegTensor<uint32_t>&)dstReg);
    } else {
        if constexpr (IsSameType<T2, int16_t>::value) {
            Reg::RegTensor<half> tmpReg;
            Reg::Cast<half, int16_t, CastParam::s162HalfTrait>(tmpReg, src0Reg, mask);
            Reg::Cast<int8_t, half, CastParam::AddReluCastTrait>(dstReg, tmpReg, mask);
        } else {
            Reg::Cast<T1, T2, CastParam::AddReluCastTrait>(dstReg, src0Reg, mask);
        }
        Reg::Pack<uint8_t, uint16_t, Reg::HighLowPart::LOWEST>(
            (Reg::RegTensor<uint8_t>&)dstReg, (Reg::RegTensor<uint16_t>&)dstReg);
    }
}

