template <typename T, typename U, typename RegT, typename RegU>
__simd_callee__ inline void Axpy(RegT& dstReg, RegU& srcReg, U scalarValue, Reg::MaskReg& mask)
{
    if constexpr (SupportType<
                      Tuple<T, U>, Tuple<half, half>, Tuple<float, float>, Tuple<uint64_t, uint64_t>,
                      Tuple<int64_t, int64_t>>()) {
        Reg::Axpy(dstReg, srcReg, scalarValue, mask);
    } else if constexpr (SupportType<Tuple<T, U>, Tuple<bfloat16_t, bfloat16_t>>()) {
        RegT tmpReg;
        Reg::Duplicate(tmpReg, scalarValue, mask);
        Reg::Mul(tmpReg, srcReg, tmpReg, mask);
        Reg::Add(dstReg, tmpReg, dstReg, mask);
    } else if constexpr (SupportType<Tuple<T, U>, Tuple<float, half>>()) {
        RegU tmpReg;
        RegT cvtReg;
        Reg::UnPack<uint32_t, uint16_t, AscendC::Reg::HighLowPart::LOWEST>(
            (Reg::RegTensor<uint32_t>&)tmpReg, (Reg::RegTensor<uint16_t>&)srcReg);
        Reg::Cast<float, half, CastParam::half2floatTrait>(cvtReg, tmpReg, mask);
        Reg::Muls(cvtReg, cvtReg, static_cast<T>(scalarValue), mask);
        Reg::Add(dstReg, cvtReg, dstReg, mask);
    }
}

__simd_vf__ inline void BilinearInterpolationRepeatModeLevel0VFImpl(
    __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ uint32_t* src0Offset, __ubuf__ T* src1,
    const BasicAPIMaskStruct maskArrayStruct, const uint64_t maskCount, const uint8_t hRepeat, const uint8_t vRepeat,
    uint16_t dstBlkStride, uint16_t vROffset, __ubuf__ uint64_t* maskBuf)
{
    uint32_t count = VecMicroGetCount<true, true, isMaskBitMode>(maskArrayStruct.maskArray, maskCount, maskBuf);
    Reg::MaskReg maskFull = Reg::CreateMask<T>();
    ;
    Reg::MaskReg maskReg = VecMicroGetMaskReg<T, true, true, isMaskBitMode>(maskBuf, count);
    Reg::RegTensor<T> dstReg;
    Reg::RegTensor<T> srcReg0;
    Reg::RegTensor<T> srcReg1;
    Reg::RegTensor<T> tmpReg;
    Reg::RegTensor<uint32_t> indexReg;

    for (uint16_t i = 0; i < static_cast<uint16_t>(vRepeat); ++i) {
        Reg::Duplicate(dstReg, static_cast<T>(0), maskFull);
        for (uint16_t j = 0; j < static_cast<uint16_t>(hRepeat); ++j) {
            Reg::LoadAlign(indexReg, src0Offset + i * hRepeat * DEFAULT_REPEAT_STRIDE + j * DEFAULT_REPEAT_STRIDE);
            Reg::GatherB(srcReg0, src0, indexReg, maskFull);

            Reg::LoadAlign<T, Reg::LoadDist::DIST_E2B_B16>(
                srcReg1, src1 + i * hRepeat * DEFAULT_BLK_NUM + j * DEFAULT_BLK_NUM);

            Reg::Mul(tmpReg, srcReg0, srcReg1, maskReg);
            Reg::Add(dstReg, tmpReg, dstReg, maskReg);
        }
        Reg::StoreAlign<T, Reg::DataCopyMode::DATA_BLOCK_COPY>(dst + i * vROffset, dstReg, dstBlkStride, maskReg);
    }
}

template <typename T>
__aicore__ inline void BrcbImpl(
    __ubuf__ T* dst, __ubuf__ T* src, const uint8_t repeatTime, const BrcbRepeatParams& repeatParams)
{
    static_assert(
        SupportBytes<T, 1, 2, 4, 8>(),
        "Failed to check dtype in Brcb, current api support dtype"
        "combination is src and dst both: uint8_t, int8_t, uint16_t, int16_t, uint32_t, int32_t, half, float, "
        "bfloat16_t, uint64_t, int64_t.");

    int32_t dstBlkStride = repeatParams.dstBlkStride ? repeatParams.dstBlkStride : 1;
    if constexpr (sizeof(T) == 8) {
        BrcbB64Impl<T>(dst, src, repeatTime, repeatParams, dstBlkStride);
    } else if constexpr (sizeof(T) == 1) {
        BrcbB8Impl<T>(dst, src, repeatTime, repeatParams, dstBlkStride);
    } else {
        BrcbCommonImpl<T>(dst, src, repeatTime, repeatParams, dstBlkStride);
    }
}

__SIMT_DEVICE_FUNCTIONS_DECL__ inline T Cast(U x)
{
    if constexpr (
        roundMode == RoundMode::CAST_EVEN || roundMode == RoundMode::CAST_ZERO || roundMode == RoundMode::CAST_FLOOR ||
        roundMode == RoundMode::CAST_CEIL) {
        static_assert(
            SupportTypeSimtInternel<
                Tuple<U, T>, Tuple<float, int>, Tuple<int, float>, Tuple<float, int64_t>, Tuple<int64_t, float>,
                Tuple<float, half>, Tuple<float, bfloat16_t>>,
            "Input type (U, T) only supports"
            "[(float, int), (int, float), (float, int64), (int64, float), (float, half), (float, bfloat16)]");
    } else if constexpr (roundMode == RoundMode::CAST_NONE) {
        static_assert(
            SupportTypeSimtInternel<Tuple<U, T>, Tuple<half, float>, Tuple<bfloat16_t, float>>,
            "Input type (U, T) only supports [(half, float), (bfloat16, float)]");
    } else {
        static_assert(
            roundMode == RoundMode::CAST_EVEN || roundMode == RoundMode::CAST_ZERO ||
                roundMode == RoundMode::CAST_FLOOR || roundMode == RoundMode::CAST_CEIL ||
                roundMode == RoundMode::CAST_NONE,
            "Cast: An invalid RoundMode!");
    }
    return CastImpl<T, U, roundMode, satMode>(x);
}

template <typename U, typename T, bool isVecDeq, bool halfBlock>
__aicore__ inline void CastDeqImpl(__ubuf__ U* dst, __ubuf__ T* src, const uint32_t calCount)
{
    static_assert(
        SupportType<Tuple<T, U>, Tuple<int16_t, int8_t>, Tuple<int16_t, uint8_t>, Tuple<int32_t, half>>(),
        "Failed to check dtype in CastDeqImpl, current api support dtype combination is src: int16_t dst: "
        "int8_t/uint8_t"
        ", src:int32_t dst:half.");
    if constexpr (IsSameType<T, int32_t>::value) {
        half scale = Internal::g_deqValue;
        CastDeqS322f16ImplVF<U, T>(dst, src, calCount, scale);
    } else {
        uint64_t deqScale = Internal::g_deqScale;
        if constexpr (isVecDeq) {
            CastVecDeqImplVF<U, T, halfBlock>(dst, src, calCount, deqScale);
        } else {
            bool signMode = GetCastDeqSignMode(deqScale);
            if (signMode) {
                CastDeqImplVF<U, T, halfBlock, true>(dst, src, calCount, deqScale);
            } else {
                CastDeqImplVF<U, T, halfBlock, false>(dst, src, calCount, deqScale);
            }
        }
    }
}

