template <typename T>
__aicore__ inline void GatherMaskCal(
    __ubuf__ T* dst, __ubuf__ T* src0, const uint8_t src1Pattern, const bool reduceMode, const uint32_t mask,
    const GatherMaskParams& reducev2Params, uint64_t& rsvdCnt)
{
    if (src1Pattern == 1) {
        GatherMaskSqueeze<T, 1>(dst, src0, reduceMode, mask, reducev2Params, rsvdCnt);
    } else if (src1Pattern == 2) {
        GatherMaskSqueeze<T, 2>(dst, src0, reduceMode, mask, reducev2Params, rsvdCnt);
    } else if (src1Pattern == 3) {
        GatherMaskSqueeze<T, 3>(dst, src0, reduceMode, mask, reducev2Params, rsvdCnt);
    } else if (src1Pattern == 4) {
        GatherMaskSqueeze<T, 4>(dst, src0, reduceMode, mask, reducev2Params, rsvdCnt);
    } else if (src1Pattern == 5) {
        GatherMaskSqueeze<T, 5>(dst, src0, reduceMode, mask, reducev2Params, rsvdCnt);
    } else if (src1Pattern == 6) {
        GatherMaskSqueeze<T, 6>(dst, src0, reduceMode, mask, reducev2Params, rsvdCnt);
    } else if (src1Pattern == 7) {
        GatherMaskAll(dst, src0, reduceMode, mask, reducev2Params, rsvdCnt);
    } else {
        ASCENDC_ASSERT((false), { KERNEL_LOG(KERNEL_ERROR, "GatherMask Pattern can only be 1~7"); });
    }
}

__simd_vf__ inline void GatherbImpl(
    __ubuf__ T* dst, __ubuf__ T* src, __ubuf__ uint32_t* srcOffsetLocal, const uint8_t repeatTime,
    const GatherRepeatParams repeatParams)
{
    constexpr uint32_t oneBlkNum = static_cast<uint32_t>(ONE_BLK_SIZE / sizeof(T));
    Reg::RegTensor<T> srcReg;
    Reg::RegTensor<T> dstReg;
    Reg::RegTensor<uint32_t> indexReg;
    Reg::MaskReg fullPreg = Reg::CreateMask<uint8_t>();

    constexpr uint32_t sregLower = static_cast<uint32_t>(GetVecLen() / sizeof(T));
    for (uint16_t i = 0; i < static_cast<uint16_t>(repeatTime); ++i) {
        Reg::LoadAlign(indexReg, srcOffsetLocal + i * DEFAULT_BLK_NUM);
        if constexpr (sizeof(T) == 8) {
            // pg is the predicate for block index, and regarded as B32 format.
            // For convenience, we use fullPreg format to represent it.
            Reg::GatherB(dstReg, src, indexReg, fullPreg);
            Reg::StoreAlign<uint32_t, Reg::DataCopyMode::DATA_BLOCK_COPY, Reg::PostLiteral::POST_MODE_UPDATE>(
                (__ubuf__ uint32_t*&)dst, (Reg::RegTensor<uint32_t>&)dstReg,
                static_cast<uint32_t>(repeatParams.dstBlkStride), static_cast<uint32_t>(repeatParams.dstRepStride),
                fullPreg);
        } else {
            Reg::GatherB(dstReg, src, indexReg, fullPreg);
            Reg::StoreAlign<T, Reg::DataCopyMode::DATA_BLOCK_COPY>(
                dst + i * repeatParams.dstRepStride * oneBlkNum, dstReg, repeatParams.dstBlkStride, fullPreg);
        }
    }
}

