__aicore__ inline void InitDetermineComputeWorkspaceCalc(
    GlobalTensor<int32_t>& gmWorkspace, LocalTensor<int32_t>& ubWorkspace)
{
    if ASCEND_IS_AIV {
        PipeBarrier<PIPE_ALL>();
        event_t eventID;
        auto blockNum = GetBlockNum();
        if (GetBlockIdx() == 0) {
            DuplicateImpl((__ubuf__ int32_t*)ubWorkspace.GetPhyAddr(), 0, B32_DATA_NUM_PER_BLOCK * blockNum);
            eventID = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_MTE3));
            SetFlag<HardEvent::V_MTE3>(eventID);
            WaitFlag<HardEvent::V_MTE3>(eventID);
            DataCopy(gmWorkspace, ubWorkspace, B32_DATA_NUM_PER_BLOCK * blockNum);
        }
        ubWorkspace.SetValue(blockNum * B32_DATA_NUM_PER_BLOCK, 1);
        PipeBarrier<PIPE_ALL>();
    }
}

template <typename T>
__aicore__ inline void InterleaveImpl(
    __ubuf__ T* dst0Local, __ubuf__ T* dst1Local, __ubuf__ T* src0Local, __ubuf__ T* src1Local, const int32_t calCount)
{
    static_assert(
        SupportType<
            T, uint8_t, int8_t, uint16_t, int16_t, uint32_t, int32_t, half, float, bfloat16_t, uint64_t, int64_t>(),
        "current data type is not supported on current device!");
    ASCENDC_ASSERT((calCount % 2 == 0), { KERNEL_LOG(KERNEL_ERROR, "calCount % 2 = 0!"); });
    if constexpr (sizeof(T) != 8) {
        if (calCount * sizeof(T) / 2 % ONE_BLOCK_SIZE == 0) {
            InterleaveImplNormal<T, false>(dst0Local, dst1Local, src0Local, src1Local, calCount);
        } else {
            InterleaveImplNormal<T, true>(dst0Local, dst1Local, src0Local, src1Local, calCount);
        }
    } else {
        if (calCount * sizeof(T) / 2 % ONE_BLOCK_SIZE == 0) {
            InterleaveImplB64<T, false>(dst0Local, dst1Local, src0Local, src1Local, calCount);
        } else {
            InterleaveImplB64<T, true>(dst0Local, dst1Local, src0Local, src1Local, calCount);
        }
    }
}

