template <typename CubeMsgType>
__aicore__ inline uint16_t CubeResGroupHandle<CubeMsgType>::PostFakeMsg(__gm__ CubeMsgType* msg)
{
    if ASCEND_IS_AIV {
        __WriteGmStateByScalar(msg, CubeMsgState::FAKE);
