template <
    typename T, typename RegT, bool precisionMode = false, const Reg::SqrtSpecificMode* sqrtMode = nullptr,
    const Reg::DivSpecificMode* divMode = nullptr>
__simd_callee__ inline void Rsqrt(RegT& dstReg, RegT& srcReg, Reg::MaskReg& mask)
{
    Reg::MaskReg cmpMask;
    Reg::Duplicate<T>(dstReg, static_cast<T>(1.0f), mask);
    Reg::CompareScalar<T, CMPMODE::LT>(cmpMask, srcReg, static_cast<T>(0.0f), mask);
    if constexpr (!precisionMode) {
        Reg::Sqrt<T, sqrtMode>(srcReg, srcReg, mask);
        Reg::Div<T, divMode>(dstReg, dstReg, srcReg, mask);
        Reg::Select(dstReg, srcReg, dstReg, cmpMask);
    } else {
        if constexpr (SupportType<T, half>()) {
            static constexpr AscendC::Reg::SqrtSpecificMode SqrtMode = {
                Reg::MaskMergeMode::ZEROING, false, SqrtAlgo::PRECISION_1ULP_FTZ_FALSE};
            Reg::Sqrt<T, &SqrtMode>(srcReg, srcReg, mask);
            static constexpr AscendC::Reg::DivSpecificMode precisionDivMode = {
                Reg::MaskMergeMode::ZEROING, false, DivAlgo::PRECISION_1ULP_FTZ_FALSE};
            Reg::Div<T, &precisionDivMode>(dstReg, dstReg, srcReg, mask);
        } else {
            static constexpr AscendC::Reg::SqrtSpecificMode SqrtMode = {
                Reg::MaskMergeMode::ZEROING, false, SqrtAlgo::PRECISION_0ULP_FTZ_FALSE};
            Reg::Sqrt<T, &SqrtMode>(srcReg, srcReg, mask);
            static constexpr AscendC::Reg::DivSpecificMode precisionDivMode = {
                Reg::MaskMergeMode::ZEROING, false, DivAlgo::PRECISION_0ULP_FTZ_FALSE};
            Reg::Div<T, &precisionDivMode>(dstReg, dstReg, srcReg, mask);
        }
    }
}

template <typename T>
__aicore__ inline void ScatterImpl(
    __ubuf__ T* dstLocal, __ubuf__ T* srcLocal, __ubuf__ uint32_t* dstOffsetLocal, const uint32_t dstLength,
    const uint32_t dstBaseAddr, const uint64_t mask, const uint8_t repeatTime, const uint8_t srcRepStride)
{
    static_assert(SupportBytes<T, 2, 4, 8>(), "Scatter only support type b16/b32/b64 on current device");
    bool isNormalMode = !Internal::IsCounterMode();
    uint32_t dstBaseOffset = dstBaseAddr / sizeof(T);
    if (isNormalMode) {
        if constexpr (sizeof(T) == 2) {
            ScatterImplB16<T, true, false>(
                dstLocal, srcLocal, dstOffsetLocal, dstLength, dstBaseOffset, mask, repeatTime, srcRepStride);
        } else if constexpr (sizeof(T) == 4) {
            ScatterImplB32<T, true, false>(
                dstLocal, srcLocal, dstOffsetLocal, dstLength, dstBaseOffset, mask, repeatTime, srcRepStride);
        } else if constexpr (sizeof(T) == 8) {
            dstBaseOffset = dstBaseAddr / sizeof(uint32_t);
            ScatterImplB64<T, true, false>(
                dstLocal, srcLocal, dstOffsetLocal, dstLength, dstBaseOffset, mask, repeatTime, srcRepStride);
        }
    } else {
        uint8_t newRepeatTimes = static_cast<uint8_t>(Internal::VecMicroGetRepeatTimes<T, false>(mask, repeatTime));
        if constexpr (sizeof(T) == 2) {
            ScatterImplB16<T, false, false>(
                dstLocal, srcLocal, dstOffsetLocal, dstLength, dstBaseOffset, mask, newRepeatTimes, srcRepStride);
        } else if constexpr (sizeof(T) == 4) {
            ScatterImplB32<T, false, false>(
                dstLocal, srcLocal, dstOffsetLocal, dstLength, dstBaseOffset, mask, newRepeatTimes, srcRepStride);
        } else if constexpr (sizeof(T) == 8) {
            dstBaseOffset = dstBaseAddr / sizeof(uint32_t);
            ScatterImplB64<T, false, false>(
                dstLocal, srcLocal, dstOffsetLocal, dstLength, dstBaseOffset, mask, newRepeatTimes, srcRepStride);
        }
    }
}

